// This class orchestrates the Copilot → ACS → Meta WPP → Blockchain pipeline
// using the Azure SDK for .NET.

using System;
using System.Text.Json;
using System.Threading.Tasks;
using Azure.AI.OpenAI;
using Azure.Communication.Messages;
using Azure.Communication.Messages.Models;

namespace Manusme.ACS
{
    /// <summary>
    /// Represents the Modulation Instruction Set generated by Azure Copilot.
    /// </summary>
    public class ModulationInstructionSet
    {
        public string Strategy      { get; set; } = "answer_query";
        public string ResponseText  { get; set; } = string.Empty;
        public string AiTone        { get; set; } = "professional";
        public bool   Escalate      { get; set; } = false;
        public bool   RecordIntent  { get; set; } = true;
    }

    /// <summary>
    /// Orchestrates the full generative communication pipeline:
    /// Copilot (Gen AI) → ACS Modulation → Meta WPP → Azure Blockchain
    /// </summary>
    public class AcsModulationEngine
    {
        private readonly OpenAIClient              _openAiClient;
        private readonly NotificationMessagesClient _acsClient;
        private readonly string                    _deploymentName;
        private readonly string                    _channelId;

        public AcsModulationEngine(
            string openAiEndpoint,
            string openAiApiKey,
            string acsConnectionString,
            string wppChannelId,
            string deploymentName = "gpt-4o")
        {
            _openAiClient   = new OpenAIClient(new Uri(openAiEndpoint), new Azure.AzureKeyCredential(openAiApiKey));
            _acsClient      = new NotificationMessagesClient(acsConnectionString);
            _channelId      = wppChannelId;
            _deploymentName = deploymentName;
        }

        // =====================================================================
        // STEP 1 — Copilot generates the Modulation Instruction Set
        // =====================================================================

        public async Task<ModulationInstructionSet> GenerateMisAsync(
            string userMessage,
            string userNumber)
        {
            const string systemPrompt = @"
You are Copilot, the generative AI brain of the ACS-WPP Interplanetary AI Mesh.
Analyse the incoming WhatsApp message and return a JSON Modulation Instruction Set (MIS):
{
  ""strategy"": ""answer_query | proactive_upsell | escalate_human"",
  ""response_text"": ""<exact message to send>"",
  ""ai_tone"": ""professional | empathetic | enthusiastic"",
  ""escalate"": false
}
Return ONLY valid JSON.";

            var chatOptions = new ChatCompletionsOptions
            {
                DeploymentName = _deploymentName,
                Messages =
                {
                    new ChatRequestSystemMessage(systemPrompt),
                    new ChatRequestUserMessage($"User: {userNumber}\nMessage: \"{userMessage}\""),
                },
                ResponseFormat = ChatCompletionsResponseFormat.JsonObject,
                Temperature = 0.7f,
            };

            var response = await _openAiClient.GetChatCompletionsAsync(chatOptions);
            var json     = response.Value.Choices[0].Message.Content;
            var mis      = JsonSerializer.Deserialize<ModulationInstructionSet>(json)
                           ?? new ModulationInstructionSet();

            Console.WriteLine($"[Copilot] MIS generated — strategy: {mis.Strategy}");
            return mis;
        }

        // =====================================================================
        // STEP 2 — ACS Modulation Engine delivers the response via Meta WPP
        // =====================================================================

        public async Task<string> ModulateAndSendAsync(
            ModulationInstructionSet mis,
            string recipientNumber)
        {
            if (mis.Escalate)
            {
                Console.WriteLine("[ACS] Escalating to human agent.");
                return "escalated";
            }

            var messageContent = new TextNotificationContent(
                channelRegistrationId: Guid.Parse(_channelId),
                to: new[] { recipientNumber },
                content: mis.ResponseText
            );

            var response  = await _acsClient.SendAsync(messageContent);
            var messageId = response.Value.Receipts.Count > 0
                ? response.Value.Receipts[0].MessageId
                : "unknown";

            Console.WriteLine($"[ACS] Delivered via Meta WPP. Message ID: {messageId}");
            return messageId;
        }

        // =====================================================================
        // FULL PIPELINE ORCHESTRATION
        // =====================================================================

        public async Task RunPipelineAsync(string userMessage, string userNumber)
        {
            Console.WriteLine($"\n{"=",60}");
            Console.WriteLine($"[Pipeline] Incoming from {userNumber}: \"{userMessage}\"");
            Console.WriteLine($"{"=",60}");

            // Step 1 — Copilot
            var mis = await GenerateMisAsync(userMessage, userNumber);

            // Step 2 — ACS → Meta WPP
            var acsMessageId = await ModulateAndSendAsync(mis, userNumber);

            // Step 3 — Blockchain anchor (fire-and-forget)
            _ = Task.Run(() => AnchorToBlockchain(userNumber, userMessage, mis, acsMessageId));

            Console.WriteLine($"\n[Pipeline] ✅ Full loop complete.");
            Console.WriteLine($"  Strategy  : {mis.Strategy}");
            Console.WriteLine($"  ACS Msg ID: {acsMessageId}");
            Console.WriteLine($"{"=",60}\n");
        }

        // =====================================================================
        // STEP 3 — Azure Blockchain anchor (stub — integrate web3 here)
        // =====================================================================

        private void AnchorToBlockchain(
            string sender,
            string originalMessage,
            ModulationInstructionSet mis,
            string acsMessageId)
        {
            // TODO: call WhatsAppMessageLedger.anchorMessage() via Nethereum
            Console.WriteLine($"[Blockchain] Anchoring — sender: {sender}, strategy: {mis.Strategy}, acsId: {acsMessageId}");
        }
    }
}
